def run(_context):
    import json
    import adsk.cam

    # Delete the duplicate "Face Top" operation using raw API
    cam = mb.get_cam()
    setup = None
    for s in cam.setups:
        if s.name == "Setup1":
            setup = s
            break

    if setup:
        ops = setup.operations
        for i in range(ops.count):
            op = ops.item(i)
            if op.name == "Face Top":
                op.deleteMe()
                print("Deleted 'Face Top' (duplicate)")
                break

    # Verify
    probe = mb.probe()
    print("\n=== AFTER DELETE ===")
    for op in probe["setups"][0]["operations"]:
        print(f"  {op['name']}: strategy={op['strategy']}, has_toolpath={op['has_toolpath']}, is_valid={op['is_valid']}")

