def run(_context):
    import json

    # Read and check the G-code for feed rates
    with open("C:/temp/pocket_box_setup1.nc", "r") as f:
        gcode = f.read()

    lines = gcode.split('\n')

    # Check for feed rates and spindle speeds
    print("=== FEED RATES AND SPINDLE SPEEDS ===")
    for i, line in enumerate(lines):
        if 'S' in line and 'M3' in line:
            print(f"  Line {i+1}: {line.strip()} (SPINDLE)")
        if 'F' in line and ('G1' in line or 'G3' in line or 'G2' in line):
            # Extract F value
            parts = line.split('F')
            if len(parts) > 1:
                f_val = parts[-1].strip().rstrip('.')
                try:
                    f_num = float(f_val)
                    if f_num > 50:  # Only show significant feeds (not rapids)
                        print(f"  Line {i+1}: {line.strip()} (FEED={f_num})")
                except:
                    pass

    # Also show first 30 lines
    print("\n=== FIRST 30 LINES ===")
    for i, line in enumerate(lines[:30]):
        print(f"  {i+1:4d}: {line}")

